let raw = $json.text ?? $json.output ?? $json.response ?? $json;

// If Ollama returned a JSON string, parse it.
if (typeof raw === "string") {
  raw = raw
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  raw = JSON.parse(raw);
}

function normalizeText(value) {
  if (!value) return null;

  return value
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, "")
    .replace(/\s+/g, " ")
    .trim();
}

return [
  {
    json: {
      ...raw,
      company_normalized: normalizeText(raw.company),
      job_title_normalized: normalizeText(raw.job_title),
      jd_text: $('When chat message received').item.json.chatInput
    }
  }
];

