const data = $('Normalize Job Fields').item.json;

const fieldsToCheck = [
  "location",
  "salary",
  "work_type",
  "employment_type",
  "job_url"
];

const missingFields = [];

for (const field of fieldsToCheck) {
  const value = data[field];

  if (value === null || value === undefined || value === "") {
    missingFields.push(field);
  }
}

return [
  {
    json: {
      ...data,
      missing_fields: missingFields
    }
  }
];

const data = $json;

const labels = {
  location: "Location",
  salary: "Salary",
  work_type: "Work Type",
  employment_type: "Employment Type",
  job_url: "Job URL"
};

let message = `I found the job details for ${data.job_title} at ${data.company}.\n\n`;

if (data.missing_fields.length > 0) {
  message += "I’m missing the following information:\n";

  for (const field of data.missing_fields) {
    message += `- ${labels[field]}\n`;
  }

  message += "\nPlease provide anything you know. If you don’t know a field, type `skip` for it.";
} else {
  message += "All required tracker information is available.";
}

return [
  {
    json: {
      ...data,
      clarification_message: message
    }
  }
];

const response = $json.response || $json.chatInput || $json.text || "";

const updates = {};

const lines = response.split("\n");

for (const line of lines) {
  const parts = line.split(":");
  if (parts.length < 2) continue;

  const key = parts[0].trim().toLowerCase();
  const value = parts.slice(1).join(":").trim();

  if (!value) continue;

  const normalizedValue =
    value.toLowerCase() === "skip" ? null : value;

  if (key === "location") {
    updates.location = normalizedValue;
  }

  if (key === "salary") {
    updates.salary = normalizedValue;
  }

  if (key === "work type") {
    updates.work_type = normalizedValue;
  }

  if (key === "employment type") {
    updates.employment_type = normalizedValue;
  }

  if (key === "job url") {
    updates.job_url = normalizedValue;
  }
}

return [
  {
    json: {
      ...updates
    }
  }
];

